const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 leaf:'M20 4C8 3 3 8 5 16c7 5 16-1 15-12Z M5 20l10-10',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 12h10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm4-4a4 4 0 0 1 0 8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 10h18c0-3-3-3-3-10M10 21h4',person:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',book:'M12 5v16M3 3c4-1 6 0 9 2 3-2 5-3 9-2v16c-4-1-6 0-9 2-3-2-5-3-9-2Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',video:'M3 5h13v14H3Zm13 5 5-3v10l-5-3',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 4v16M4 12h16',play:'m8 4 12 8-12 8Z',pause:'M8 4v16M16 4v16',check:'m4 12 5 5L20 6',close:'m6 6 12 12M6 18 18 6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z M8 12l3 3 5-6',logout:'M9 3H3v18h6m5-5 4-4-4-4m-7 4h12',bookmark:'M6 3h12v18l-6-4-6 4Z',heart:'M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-5 4 0 10 8 16 8-6 13-12 8-16Z',chat:'M21 3H3v14h5l4 4 4-4h5Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',location:'M12 22s8-9 8-14a8 8 0 0 0-16 0c0 5 8 14 8 14ZM15 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',camera:'M3 6h5l2-3h4l2 3h5v14H3ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',image:'M3 3h18v18H3Zm0 14 5-5 4 4 4-6 5 8M8 7h1',volume:'m3 9 5 0 5-5v16l-5-5H3ZM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',sparkles:'m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3Zm8-2v4m-2-2h4',phone:'M7 2h10v20H7ZM11 18h2',tag:'m3 3 10 0 8 8-10 10-8-8ZM7 7h1',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',wheat:'M12 22V4m0 5C5 9 5 4 5 4s7 0 7 5Zm0 6c-7 0-7-5-7-5s7 0 7 5Zm0-3c7 0 7-5 7-5s-7 0-7 5Zm0 6c7 0 7-5 7-5s-7 0-7 5Z'};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n] || paths.leaf}"/></svg>`;
const KEY = 'gengyun-ui-demo-v1';
let saved = {}; try { saved = JSON.parse(localStorage.getItem(KEY) || '{}'); } catch {}
const S = {logged:true,name:'田间探索者',crop:'水稻',favorites:[],likes:[],posts:[],read:[],voice:false,...saved,route:'home',scanMode:'weed',photo:'',scanning:false,progress:0,videoName:'演示制剂 A',period:'recent',videoReady:false,playing:false,time:0,generating:false,chats:[],chatBusy:false};
const persist = () => {try {localStorage.setItem(KEY,JSON.stringify(Object.fromEntries(['logged','name','crop','favorites','likes','posts','read','voice'].map(k=>[k,S[k]]))));} catch {}};
let processTimer, chatTimer, frame, lastFrame=0, toastTimer, recordingTimer, modalFocus;
const articles = [
 {id:'rice',title:'水稻',cat:'作物',icon:'wheat',color:'',regions:['湖南','浙江'],intro:'认识作物，记录生长阶段与田间观察。',body:'常见地区标签为界面示例，正式资料需补充核验来源。'},
 {id:'corn',title:'玉米',cat:'作物',icon:'wheat',color:'amber',regions:['湖南','山东'],intro:'从叶片、植株与生长阶段建立观察记录。',body:'本页演示作物资料和地区分类，不代表完整种植范围。'},
 {id:'vegetable',title:'蔬菜',cat:'作物',icon:'leaf',color:'',regions:['上海','浙江'],intro:'整理蔬菜作物的资料与观察笔记。',body:'本页仅展示资料排版，后续按具体作物补充来源。'},
 {id:'drugb',title:'演示制剂 B',cat:'农药',icon:'tag',color:'amber',regions:['湖南','浙江'],risk:'中危',toxicity:'中等毒',intro:'虚构制剂，用于体验中危与毒性筛选。',body:'产品名称、地区、危险评估及毒性全部是演示数据，不对应真实农药。'},
 {id:'drugc',title:'演示制剂 C',cat:'农药',icon:'shield',color:'blue',regions:['上海','山东'],risk:'高危',toxicity:'高毒',intro:'虚构制剂，用于体验高危与毒性筛选。',body:'产品名称、地区、危险评估及毒性全部是演示数据，不对应真实农药。'},

 {id:'weed',title:'稗草的叶片与叶鞘',cat:'杂草',icon:'leaf',color:'',intro:'从叶形、叶鞘与生长环境，建立田间观察记录。',body:'观察植物时，可以记录整株、叶片、叶鞘和周边环境。这里展示资料详情的排版和信息层级；示例文字不代表真实识别结论。'},
 {id:'label',title:'读懂一张农药标签',cat:'标签',icon:'scan',color:'blue',intro:'先确认产品信息，再查看登记与适用范围。',body:'标签资料页面将展示产品名称、登记信息、来源和资料版本。正式产品应以核验的标签原文为准；本页不包含真实登记资料或用量。'},
 {id:'record',title:'田间观察：从记录开始',cat:'农事',icon:'wheat',color:'amber',intro:'将时间、地点与照片，变成连续的观察。',body:'每一次观察都是新的线索。你可以记录作物阶段、拍摄日期和发现的问题，并在社区中分享观察过程。这是前端界面示例。'},
 {id:'drug',regions:['上海','湖南','浙江'],risk:'低危',toxicity:'低毒',title:'演示制剂 A',cat:'农药',icon:'tag',color:'blue',intro:'虚构产品，用于体验扫描标签与情景视频流程。',body:'演示制剂 A 是虚构名称，仅用于 UI 体验。登记、成分、适用作物与使用方法均未提供。情景视频属于视觉创作，不表达使用后的真实效果。'},
 {id:'soil',title:'认识脚下的土壤',cat:'农事',icon:'sun',color:'amber',intro:'从颜色、结构和地表状态开始观察。',body:'本页用于展示科普内容的阅读体验。正式资料会标明来源、版本和适用条件，当前内容为演示占位。'},
 {id:'safety',title:'建立清晰的标签记录',cat:'标签',icon:'shield',color:'',intro:'保持照片完整，保留文字与版本信息。',body:'扫描流程支持确认和修正文本。本 Demo 不读取图片内容，仅模拟识别步骤，帮助体验信息确认界面。'}];
const seedPosts = [
 {id:'p1',name:'禾间笔记',crop:'水稻',time:'20 分钟前 · 示例',text:'今天给田边的植株做了一次观察记录。拍整株和叶鞘，确实比只拍一片叶子更容易整理线索。',art:true,likes:18,comments:3},
 {id:'p2',name:'小林的田间日记',crop:'玉米',time:'1 小时前 · 示例',text:'把一周的田间照片按日期放在一起，变化一下就清楚了。你们平时都怎么整理农事记录？',art:false,likes:12,comments:2}];
const notifications=[{id:'n1',title:'禾间笔记回复了你的观察',text:'“可以再补一张叶鞘的近照。”',type:'interaction',icon:'chat',route:'post/p1',time:'10 分钟前'}, {id:'n2',title:'你的情景视频已准备好',text:'演示制剂 A · 近期创作片段',type:'system',icon:'video',route:'video',time:'30 分钟前'}, {id:'n3',title:'欢迎来到耕云',text:'从一次田间观察，开始探索。',type:'system',icon:'leaf',route:'home',time:'今天'}];
let libraryFilter='作物', libraryRegion='全部', libraryRisk='全部', libraryQuery='',messageFilter='all',communityFilter='全部', comments={};
const btn=(text,action,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,route,cls='text-btn')=>`<button class="${cls}" data-route="${route}">${text}</button>`;
const heading=(title,sub,back='')=>`<div class="page-heading"><div>${back?`<div class="title-with-back"><button class="back-btn" data-route="${back}" aria-label="返回">${icon('back')}</button><h1>${title}</h1></div>`:`<h1>${title}</h1>`}<p>${sub}</p></div><div class="heading-right"><button class="context-chip" data-action="crop">${icon('wheat')} ${esc(S.crop)} ${icon('settings')}</button></div></div>`;
const foot=()=>'<p class="footer-note">耕云 · 前端交互原型　/　所有人物、资料与结果均为演示数据</p>';
const card=a=>`<article class="article-card"><button class="article-art ${a.color}" data-route="article/${a.id}" aria-label="阅读${a.title}">${icon(a.icon)}<span>${a.cat} / FIELD NOTES</span></button><div class="card-meta"><span>${a.cat}</span><span>演示资料</span></div><h3>${link(a.title,`article/${a.id}`)}</h3><p>${a.intro}</p></article>`;
function home(){return `${heading('早安，田间探索者','从一次观察开始，发现更多田间可能。')}<section class="hero"><img class="hero-art" src="assets/field.svg" alt="科技感田野与植物插画"><div class="hero-content"><div class="eyebrow"><span class="dot"></span> FIELD INTELLIGENCE / 耕云</div><h2>看见田间的<br>每一种可能。</h2><p>识别一株草，读懂一张标签。<br>让每一个田间问题，都有探索的起点。</p>${link(`开始识别 ${icon('arrow')}`,'identify','btn lime')}</div><span class="hero-code">OBSERVE · UNDERSTAND · EXPLORE</span></section><section class="section"><div class="section-head"><h2>你的田间工具</h2><span class="compact-meta">四个入口，一个探索旅程</span></div><div class="feature-grid">${[['leaf','拍照识草','留住田间的新发现','identify',''],['scan','扫描标签','让复杂信息更清晰','identify/label',''],['chat','农事问答','把问题说给耕云听','chat',''],['video','情景视频','看见时间里的想象','video','NEW']].map(([i,t,d,r,n])=>`<button class="feature-card" data-route="${r}"><div class="feature-icon">${icon(i)}</div>${n?`<span class="new-tag">${n}</span>`:''}<h3>${t}</h3><p>${d}</p><span class="card-arrow">${icon('arrow')}</span></button>`).join('')}</div></section><div class="home-bottom"><section class="panel"><div class="panel-head"><h2>田间知识，一点点积累</h2>${link('查看资料库 '+icon('arrow'),'library')}</div><div class="info-list">${articles.slice(0,3).map(a=>`<button class="info-row" data-route="article/${a.id}"><span class="tiny-art">${icon(a.icon)}</span><span class="copy"><strong>${a.title}</strong><small>${a.intro}</small></span><span class="pill">${a.cat}</span></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>今天的探索</h2><span class="pill gray">示例记录</span></div><div class="mini-timeline">${[['完成一次田间观察','拍照识草 · 09:20','identify'],['读懂标签上的信息','标签资料 · 09:35','article/label'],['看见二十年后的想象','情景视频 · 等待你探索','video']].map(([t,d,r])=>`<button class="timeline-item" data-route="${r}"><span class="timeline-dot"></span><span class="timeline-copy"><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div></section></div>${foot()}`;}
function identify(){const label=S.scanMode==='label';return `${heading('每一次发现，都值得看清','拍下植物或标签，开启一次田间探索。')}<div class="tabs">${['weed','label'].map(m=>`<button class="${S.scanMode===m?'active':''}" data-action="scan-mode" data-mode="${m}">${icon(m==='weed'?'leaf':'scan')} ${m==='weed'?'拍照识草':'扫描标签'}</button>`).join('')}</div><div class="scan-grid"><section class="panel scan-stage"><div class="scan-view"><div class="scan-frame">${S.photo?`<img src="${S.photo}" alt="本地选取的图片" style="width:100%;height:100%;object-fit:contain">`:icon(label?'scan':'leaf')}</div><div class="scan-caption"><strong>${label?'让标签信息更清晰':'遇见一株不认识的草？'}</strong><p>${label?'拍摄完整标签，保持文字清晰':'将植株放入取景框，保留叶片与叶鞘'}</p></div></div><div class="row-actions">${btn(icon('image')+' 选择照片','upload','ghost')}${btn('使用示例','sample','ghost')}</div><p class="demo-caption">照片仅在本页本地预览。Demo 不读取图片内容。</p></section><section class="panel"><div class="panel-head"><h2>${label?'确认标签，再查资料':'从观察，到了解'}</h2><span class="pill">前端模拟</span></div><p class="hint">${label?'体验扫描、文本确认、资料查询和情景视频的完整界面流程。':'体验候选结果、特征查看和资料收藏。实际识别能力将在正式版本接入。'}</p><div class="sample"><span class="tiny-art">${icon(label?'tag':'wheat')}</span><div><strong>${label?'演示制剂 A':'田边的示例植株'}</strong><p>内置界面示例 · 无需拍照也可体验</p></div></div><div class="process-panel ${S.scanning?'running':''}"><div class="process-status"><span>${S.scanning?'正在模拟识别…':'准备好开始了吗？'}</span><b id="scan-percent">${S.scanning?S.progress+'%':'READY'}</b></div><div class="progress-track"><span id="scan-progress" style="width:${S.progress}%"></span></div><div class="process-steps"><span>01 图片确认</span><span>02 模拟分析</span><span>03 整理结果</span></div></div>${btn(S.scanning?'正在识别…':icon('scan')+' 开始识别','scan','primary full',S.scanning?'disabled':'')}<p class="demo-caption">识别结果为预置示例，不代表真实识别或准确率。</p></section></div>${foot()}`;}
function result(){const label=S.scanMode==='label';return `${heading(label?'先确认，再探索':'发现了新的田间线索','以下为前端模拟结果，仅供界面体验。','identify')}<div class="detail-layout"><section class="panel"><div class="result-hero">${icon(label?'tag':'leaf')}<span class="pill">${label?'模拟 OCR':'模拟识别'}</span><h2>${label?'演示制剂 A':'稗草 · 示例候选'}</h2><p>${label?'请确认产品名称，之后可进入资料与视频页面。':'结合植株细节，了解候选结果的呈现方式。'}</p></div>${label?`<label class="label" for="confirmed-name">确认产品名称</label><input id="confirmed-name" class="input" maxlength="80" value="${esc(S.videoName)}"><div class="stat-grid"><div class="stat"><small>登记信息</small><strong>待核验</strong></div><div class="stat"><small>成分与用量</small><strong>未提供</strong></div></div><p class="notice">产品名称为虚构示例。正式使用信息须来自核验资料。</p><div class="row-actions">${link('查看资料','article/drug','btn ghost')}${btn(icon('video')+' 情景视频','result-video')}</div>`:`${[['稗草','82%'],['狗尾草','12%'],['其他候选','6%']].map(([n,p],i)=>`<div class="result-candidate"><span class="tiny-art">${icon('leaf')}</span><div><strong>${n}</strong><small>${i===0?'优先候选 · 示例':'其他候选 · 示例'}</small></div><b>${p}</b></div>`).join('')}<p class="demo-caption">比例是界面占位，不是模型准确率或真实置信度。</p><div class="row-actions">${link('了解植株特征','article/weed','btn primary')}${link('继续提问','chat','btn ghost')}</div>`}</section><aside class="panel prose"><h2>观察，让线索更完整</h2><p>可以记录整株、叶片与周边环境；标签照片则应保留产品信息和完整文字。</p><div class="notice">这里展示确认信息与继续探索的交互，不提供用药建议。</div><h3>接下来可以</h3><p>阅读资料、收藏发现，或向耕云提出问题。</p>${link('打开资料库 '+icon('arrow'),'library')}</aside></div>${foot()}`;}
function communitySwitch(selected){return `<nav class="tabs community-switch" aria-label="社区与资料库切换">${['community','library'].map((r,i)=>`<button data-route="${r}" class="${selected===r?'active':''}" aria-current="${selected===r?'page':'false'}">${i?'资料库':'社区'}</button>`).join('')}</nav>`;}
function infoTags(a){return `<div class="info-tags">${a.regions?`<span class="tag-label">常见地区</span>${a.regions.map(r=>`<span class="pill">${r}</span>`).join('')}`:''}${a.risk?`<span class="pill risk-${a.risk==='低危'?'low':a.risk==='中危'?'medium':'high'}">危险评估 · ${a.risk}</span><span class="pill gray">毒性 · ${a.toxicity}</span>`:''}</div>`;}
function library(){return `${communitySwitch('library')}${heading('田间资料库','作物与农药，按地区和毒性快速查找。')}<div class="tabs" aria-label="资料类型">${['作物','农药','全部'].map(c=>`<button class="${libraryFilter===c?'active':''}" data-action="category" data-category="${c}">${c==='全部'?'全部资料':c}</button>`).join('')}</div><div class="search-box">${icon('search')}<input id="library-search" class="input" placeholder="搜索作物、农药或资料名称" value="${esc(libraryQuery)}" aria-label="搜索资料"></div><div class="library-filters"><label>常见地区<select class="input" id="library-region">${['全部','上海','湖南','浙江','山东'].map(v=>`<option ${libraryRegion===v?'selected':''}>${v}</option>`).join('')}</select></label>${libraryFilter==='农药'?`<label>毒性分类<select class="input" id="library-risk">${['全部','低毒','中等毒','高毒'].map(v=>`<option ${libraryRisk===v?'selected':''}>${v}</option>`).join('')}</select></label>`:''}</div><p class="demo-caption library-note">地区、危险评估与毒性标签为演示数据；危险评估与毒性分别展示。</p><div id="library-results" class="library-grid">${libraryCards()}</div>${foot()}`;}
function libraryCards(){const list=articles.filter(a=>(libraryFilter==='全部'||a.cat===libraryFilter)&&(libraryRegion==='全部'||a.regions?.includes(libraryRegion))&&(libraryFilter!=='农药'||libraryRisk==='全部'||a.toxicity===libraryRisk)&&(a.title+a.intro+(a.regions||[]).join('')).includes(libraryQuery));return list.length?list.map(a=>card(a).replace('<div class="card-meta">',infoTags(a)+'<div class="card-meta">')).join(''):'<div class="empty">没有匹配的资料，试试其他地区或毒性分类。</div>';}
function article(id){const a=articles.find(a=>a.id===id);if(!a)return library();return `${heading(a.title,'演示资料 · 内容与来源待正式版本核验','library')}<div class="detail-layout"><article class="panel prose"><div class="article-art ${a.color}">${icon(a.icon)}<span>FIELD NOTES / ${a.cat}</span></div><div class="card-meta"><span>${a.cat}</span><span>界面示例 · 非核准来源</span></div><h2>${a.title}</h2>${infoTags(a)}<p>${a.intro}</p><h3>先从观察开始</h3><p>${a.body}</p><h3>信息与来源</h3><div class="stat-grid"><div class="stat"><small>资料版本</small><strong>Demo v1</strong></div><div class="stat"><small>核验状态</small><strong>示例占位</strong></div></div><p class="notice">本页用于 UI 演示，不作为诊断、用药或真实效果预测依据。</p><div class="row-actions">${btn(icon('bookmark')+(S.favorites.includes(id)?' 已收藏':' 收藏资料'),'favorite','ghost',`data-id="${id}"`)}${link(icon('chat')+' 继续提问','chat','btn primary')}</div></article><aside class="panel"><h2>让知识变成新的探索</h2><p class="hint">看看相关的工具，继续你的田间旅程。</p><div class="info-list">${link(icon('scan')+' 扫描标签','identify/label','info-row')}${link(icon('video')+' 情景视频','video','info-row')}${link(icon('users')+' 交流观察','community','info-row')}</div></aside></div>${foot()}`;}
const periodNames={recent:'近期',ten:'十年',twenty:'二十年'};
function video(){return `${heading('让时间，成为一段想象','从标签到情景，探索田野里的另一种可能。')}<div class="video-layout"><section><div class="video-stage"><canvas id="video-canvas" class="video-canvas" aria-label="田野情景动画预览"></canvas><span class="watermark">演示视频 · 非真实预测</span><span class="video-status">${S.videoReady?'PREVIEW / '+periodNames[S.period]:'FIELD SIMULATION'}</span>${!S.videoReady?`<div class="video-center"><div class="generation-orb">${icon(S.generating?'sparkles':'video')}</div><strong>${S.generating?'正在构建一段想象':'你的田野，等待展开'}</strong><p>${S.generating?'浏览器正在模拟生成进度':'选择时间段，预览一段田野创作动画'}</p></div>`:''}<div class="video-controls"><button data-action="play" aria-label="播放或暂停" ${S.videoReady?'':'disabled'}>${icon(S.playing?'pause':'play')}</button><span id="video-time">${formatTime(S.time)} / 00:16</span><input id="video-seek" type="range" min="0" max="16" step="0.1" value="${S.time}" aria-label="预览进度" ${S.videoReady?'':'disabled'}><button data-action="restart" aria-label="重新播放" ${S.videoReady?'':'disabled'}>${icon('clock')}</button></div></div><div class="timeline-bar">${Object.entries(periodNames).map(([v,t],i)=>`<button class="time-node ${S.period===v?'active':''}" data-action="period" data-period="${v}"><span>0${i+1}</span><strong>${t}</strong><small>视觉创作片段</small></button>`).join('')}</div><p class="demo-caption">本地 Canvas 动画预览，不是实际 AI 生成或真实农药效果预测。</p></section><aside class="panel"><div class="panel-head"><h2>构建你的情景</h2><span class="pill purple">创作演示</span></div><label class="label" for="video-name">产品名称</label><input id="video-name" class="input" maxlength="80" value="${esc(S.videoName)}"><p class="hint">试试扫描一张标签，或使用虚构的演示制剂。</p>${link(icon('scan')+' 从标签开始','identify/label','text-btn')}<div class="form-gap"><span class="label">选择时间段</span><div class="periods">${Object.entries(periodNames).map(([v,t])=>`<button class="period ${S.period===v?'active':''}" data-action="period" data-period="${v}"><strong>${t}</strong><small>${v==='recent'?'此刻的想象':v==='ten'?'延展的田野':'远方的可能'}</small></button>`).join('')}</div></div><div class="process-panel ${S.generating?'running':''}"><div class="process-status"><span>${S.generating?'模拟生成中':S.videoReady?'预览已就绪':'准备生成'}</span><b id="video-percent">${S.generating?S.progress+'%':S.videoReady?'100%':'READY'}</b></div><div class="progress-track"><span id="video-progress" style="width:${S.generating?S.progress:S.videoReady?100:0}%"></span></div><div class="process-steps"><span>情景构思</span><span>画面展开</span><span>预览就绪</span></div></div>${btn(S.generating?'正在生成…':icon('sparkles')+(S.videoReady?' 再生成一次':' 生成情景视频'),'generate','primary full',S.generating?'disabled':'')}<p class="notice">这是一段艺术化演示。时间标签不表示真实变化，也不提供用药结论。</p></aside></div>${foot()}`;}
function chat(){return `${heading('把问题，说给耕云听','文字或语音，从一个问题开始探索。')}<section class="panel chat-layout">${!S.chats.length?`<div class="chat-intro"><div class="chat-orb">${icon('sparkles')}</div><span class="eyebrow">YOUR FIELD COMPANION</span><h2>今天，有什么田间发现？</h2><p>识别结果、标签信息、农事记录，都可以聊一聊。</p><div class="suggestions">${['如何拍摄一张清晰的标签？','我想了解稗草的观察特征','如何整理田间观察记录？'].map(t=>`<button class="chip" data-action="suggest" data-text="${t}">${t} ${icon('arrow')}</button>`).join('')}</div></div>`:''}<div class="chat-messages" id="chat-messages">${S.chats.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}"><span class="avatar">${m.role==='user'?'我':icon('leaf')}</span><div class="bubble">${m.role==='bot'?'<span class="pill">演示回答</span><br>':''}${esc(m.text)}${m.role==='bot'?`<div class="bubble-tools">${link('参考资料 · 标签记录','article/label')}${btn(icon('volume'),'speak','ghost',`aria-label="朗读演示回答" data-text="${esc(m.text)}"`)}</div>`:''}</div></div>`).join('')}${S.chatBusy?'<div class="hint">正在整理演示回答…</div>':''}</div><form id="chat-form" class="chat-entry"><button type="button" data-action="voice" aria-label="模拟语音输入">${icon('mic')}</button><input id="chat-input" maxlength="500" placeholder="输入你的田间问题…" aria-label="问答内容"><button class="send-btn" type="submit" aria-label="发送" ${S.chatBusy?'disabled':''}>${icon('arrow')}</button></form><p class="chat-footnote">前端模拟问答与语音输入 · 无真实 ASR / 大模型请求</p></section>${foot()}`;}
function postCard(p,detail=false){return `<article class="post"><div class="post-author"><span class="avatar">${esc(p.name.slice(0,1))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.time)} · ${esc(p.crop)}</small></div><span class="pill gray">示例动态</span></div><${detail?'div':'button'} class="post-text" ${detail?'':`data-route="post/${p.id}"`}>${esc(p.text)}</${detail?'div':'button'}>${p.art?`<button class="post-visual" data-route="post/${p.id}" aria-label="查看田间观察"><img src="assets/field.svg" alt="田间观察示例插画" style="width:100%;height:100%;object-fit:cover"><span>FIELD OBSERVATION / 田间观察</span></button>`:''}<div class="post-actions"><button class="${S.likes.includes(p.id)?'liked':''}" data-action="like" data-id="${p.id}">${icon('heart')} ${p.likes+(S.likes.includes(p.id)?1:0)}</button>${link(icon('chat')+' '+(p.comments+(comments[p.id]?.length||0)),`post/${p.id}`)}<button data-action="report" data-id="${p.id}">${icon('shield')} 反馈</button></div></article>`;}
function community(){const posts=[...S.posts,...seedPosts].filter(p=>communityFilter==='全部'||p.crop===S.crop);return `${communitySwitch('community')}${heading('田间的发现，值得分享','记录日常观察，和更多耕耘者一起交流。')}<div class="section-head"><div class="chips">${['全部','同作物'].map(c=>`<button class="chip ${communityFilter===c?'active':''}" data-action="feed-filter" data-filter="${c}">${c}</button>`).join('')}</div>${btn(icon('plus')+' 分享发现','compose','primary')}</div><div class="community-layout"><div class="feed">${posts.map(p=>postCard(p)).join('')||'<div class="empty">还没有同作物的示例动态，分享第一条观察吧。</div>'}</div><aside><section class="panel"><div class="panel-head"><h2>正在聊的话题</h2></div>${['# 田边的第一株草','# 一张清晰的标签','# 我的农事记录'].map(t=>`<button class="topic" data-action="topic" data-text="${t}"><strong>${t}</strong><small>看看大家的田间发现</small>${icon('arrow')}</button>`).join('')}<p class="demo-caption">社区内容为虚构示例，发布仅保存到本机。</p></section></aside></div>${foot()}`;}
function postDetail(id){const p=[...S.posts,...seedPosts].find(p=>p.id===id);if(!p)return community();return `${heading('一段田间观察','留住发现，也听听大家的想法。','community')}<section class="panel">${postCard(p,true)}<div class="comments"><h3>交流与讨论</h3>${id==='p1'?'<div class="comment-row"><span class="avatar">林</span><div><strong>小林 · 示例评论</strong><p>记录得很细致，可以再补一张叶鞘的近照。</p></div></div>':''}${(comments[id]||[]).map(t=>`<div class="comment-row"><span class="avatar">我</span><div><strong>${esc(S.name)} · 本地演示评论</strong><p>${esc(t)}</p></div></div>`).join('')}<form id="comment-form" data-id="${id}" class="row-actions"><input class="input" id="comment-input" maxlength="300" placeholder="分享你的观察…" aria-label="评论内容" required><button class="btn primary" type="submit">发送</button></form></div></section>${foot()}`;}
function messages(){return `${heading('消息，让交流继续','你的互动与探索进度，都在这里。')}<div class="section-head"><div class="chips">${[['all','全部'],['interaction','互动'],['system','系统']].map(([v,t])=>`<button class="chip ${messageFilter===v?'active':''}" data-action="message-filter" data-filter="${v}">${t}</button>`).join('')}</div>${btn('全部已读','read-all','ghost')}</div><section class="panel message-list">${notifications.filter(n=>messageFilter==='all'||n.type===messageFilter).map(n=>`<button class="message-row" data-action="message" data-id="${n.id}"><span class="message-icon">${icon(n.icon)}</span><span class="message-copy"><strong>${n.title}</strong><p>${n.text}</p><small>${n.time} · 演示消息</small></span>${!S.read.includes(n.id)?'<span class="unread-dot"></span>':icon('arrow')}</button>`).join('')}</section>${foot()}`;}
function profile(){return `${heading('我的耕云','把探索与发现，整理成自己的田间档案。')}<section class="profile-header"><span class="avatar">${esc(S.name.slice(0,1))}</span><div><h2>${S.logged?esc(S.name):'游客'}</h2><p>${esc(S.crop)} · 本地演示账号</p></div><div class="profile-actions">${btn(S.logged?'编辑资料':'体验登录',S.logged?'edit-profile':'login','ghost')}<p class="ip-location">IP 属地：上海 <small>演示</small></p></div></section><div class="stat-grid">${[[S.favorites.length,'我的收藏','favorites'],[3,'探索记录','history'],[S.posts.length,'我的发布','my-posts']].map(([n,t,a])=>`<button class="stat" data-action="${a}"><strong>${n}</strong><small>${t}</small></button>`).join('')}</div><div class="profile-grid"><section class="panel"><h2>我的偏好</h2><button class="setting-row" data-action="crop"><span>${icon('wheat')} 关注作物</span><span>${esc(S.crop)} ${icon('arrow')}</span></button><button class="setting-row" data-action="toggle-voice"><span>${icon('volume')} 问答自动朗读</span><span class="switch ${S.voice?'on':''}" role="switch" aria-checked="${S.voice}" aria-label="问答自动朗读"></span></button><button class="setting-row" data-action="privacy"><span>${icon('shield')} 隐私与授权</span>${icon('arrow')}</button></section><section class="panel"><h2>关于这次体验</h2><button class="setting-row" data-action="about"><span>${icon('leaf')} 耕云 Demo</span><span>v1.0 ${icon('arrow')}</span></button><button class="setting-row" data-action="reset"><span>${icon('settings')} 重置演示数据</span>${icon('arrow')}</button><button class="setting-row" data-action="${S.logged?'logout':'login'}"><span>${icon('logout')} ${S.logged?'退出演示账号':'体验登录'}</span>${icon('arrow')}</button><p class="demo-caption">登录、授权和资料保存均为本地模拟。</p></section></div>${foot()}`;}
const navs=[['home','home','首页'],['community','users','社区'],['identify','scan','识别'],['messages','bell','消息'],['profile','person','我的']];
function activeTab(){const r=S.route.split('/')[0];return navs.some(n=>n[0]===r)?r:['result'].includes(r)?'identify':'';}
function render(){cancelAnimationFrame(frame);lastFrame=0;const [page,id]=S.route.split('/');const content=({home,identify,result,library,video,chat,community,messages,profile}[page]||(()=>page==='article'?article(id):page==='post'?postDetail(id):home()))();const unread=notifications.filter(n=>!S.read.includes(n.id)).length;const nav=mobile=>navs.map(([r,i,t])=>`<button class="${mobile?'':'nav-item'} ${activeTab()===r?'active':''}" data-route="${r}">${icon(i)}<span>${t}</span>${r==='messages'&&unread?`<span class="badge-number">${unread}</span>`:''}</button>`).join('');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-route="home"><span class="brand-mark">${icon('leaf')}</span><span><span class="brand-name">耕云</span><span class="brand-sub" style="display:block">GENGYUN</span></span></button><div class="nav-label">田间工作台</div><nav class="nav-list" aria-label="主导航">${nav(false)}</nav><div class="sidebar-tools"><div class="nav-label">探索更多</div>${[['library','book','资料库'],['chat','chat','农事问答'],['video','video','情景视频']].map(([r,i,t])=>`<button class="nav-item ${page===r?'active':''}" data-route="${r}">${icon(i)} ${t}</button>`).join('')}</div><div class="sidebar-note"><strong><span class="dot"></span> 田间的可能，正在发生</strong>每一次观察，都是新的起点。<br>前端原型 · 数据仅在本机</div></aside><div class="workspace"><header class="topbar"><button class="mobile-brand" data-route="home">${icon('leaf')} 耕云</button><div class="crumb">工作台 <span>/</span><b>${({home:'首页',identify:'识别',result:'识别结果',library:'资料库',article:'资料详情',video:'情景视频',chat:'农事问答',community:'社区',post:'社区详情',messages:'消息',profile:'我的'})[page]||'首页'}</b></div><div class="top-actions"><span class="mode-badge"><span></span> DEMO MODE</span><button class="preview-toggle" data-action="phone">${icon('phone')} ${document.body.classList.contains('phone-mode')?'退出手机预览':'手机预览'}</button><button class="avatar" data-route="profile" aria-label="个人中心">${esc(S.name.slice(0,1))}</button></div></header><main class="main fade-in">${content}</main></div><nav class="bottom-nav" aria-label="移动端主导航">${nav(true)}</nav></div>`;if(page==='video')animateVideo();if(page==='chat'&&S.chats.length)$('#chat-messages').scrollIntoView({block:'nearest'});}
function go(route){if(!S.logged&&!['home','profile'].includes(route.split('/')[0])){login(route);return;}if(S.route===route){render();return;}location.hash=route;}
function route(){clearInterval(processTimer);S.scanning=false;S.generating=false;S.progress=0;cancelAnimationFrame(frame);window.speechSynthesis?.cancel();const r=location.hash.slice(1)||'home';S.route=/^(home|identify(?:\/label)?|result|library|article\/[a-z]+|video|chat|community|post\/[a-z0-9]+|messages|profile)$/.test(r)?r:'home';if(r==='identify/label')S.scanMode='label';render();window.scrollTo(0,0);}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function modal(title,body){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}</section></div>`;setTimeout(()=>$('.modal input,.modal button')?.focus(),20);}
function close(){ $('#modal-root').innerHTML='';modalFocus?.focus();}
function login(dest='profile'){modal('欢迎来到耕云',`<div class="login-mark">${icon('leaf')}</div><div class="login-copy"><h2>从田间，连接更多可能</h2><p>用一个演示账号，体验你的探索旅程。</p></div><form id="login-form" data-dest="${dest}"><label class="label" for="login-name">你的昵称</label><input class="input" id="login-name" maxlength="20" value="${esc(S.name)}" required><label class="agreement"><input type="checkbox" required> 我已了解这是本地前端体验</label><button class="btn primary full" type="submit">进入耕云</button></form><p class="modal-note">模拟登录，无真实微信授权或账号创建。</p>`);}
function simulate(kind){if(S.scanning||S.generating)return;S.progress=0;S[kind==='scan'?'scanning':'generating']=true;if(kind==='video'){S.videoName=$('#video-name').value.trim()||'演示制剂 A';S.videoReady=false;S.playing=false;S.time=0;}render();clearInterval(processTimer);processTimer=setInterval(()=>{S.progress=Math.min(100,S.progress+10);const prefix=kind==='scan'?'scan':'video';$('#'+prefix+'-percent').textContent=S.progress+'%';$('#'+prefix+'-progress').style.width=S.progress+'%';if(S.progress===100){clearInterval(processTimer);S.scanning=false;S.generating=false;if(kind==='scan')go('result');else{S.videoReady=true;S.playing=true;render();toast('创作预览已就绪 · 本地动画演示');}}},kind==='scan'?160:220);}
function ask(text){text=text.trim();if(!text||S.chatBusy)return;S.chats.push({role:'user',text});S.chatBusy=true;render();clearTimeout(chatTimer);chatTimer=setTimeout(()=>{const reply=text.includes('记录')?'可以试着按日期、作物和观察位置整理照片，记录每次发现。社区页面可以体验发布一条观察。这是演示回答。':text.includes('草')?'可以补充整株、叶片与叶鞘的清晰照片，并对照资料页查看观察特征。本 Demo 的识别结果是预置示例。这是演示回答。':'可以先拍摄完整、清晰的标签，再核对产品名称、登记信息与资料来源。当前 Demo 不提供真实用量或用药结论。这是演示回答。';S.chats.push({role:'bot',text:reply});S.chatBusy=false;if(S.route==='chat')render();if(S.voice&&S.route==='chat')speak(reply);},750);}
function speak(text){if(!('speechSynthesis' in window)){toast('当前浏览器不支持本地朗读');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.onerror=()=>toast('当前浏览器未能播放朗读');window.speechSynthesis.speak(u);}
function formatTime(t){return '00:'+Math.floor(t).toString().padStart(2,'0');}
function animateVideo(){const canvas=$('#video-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function draw(now){const w=canvas.clientWidth||700,h=canvas.clientHeight||370,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);if(S.playing&&lastFrame){S.time=Math.min(16,S.time+(now-lastFrame)/1000);if(S.time>=16)S.playing=false;}lastFrame=now;const t=S.time/16,period={recent:0,ten:1,twenty:2}[S.period];const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,period===2?'#122c43':period===1?'#173e3c':'#123a30');sky.addColorStop(1,'#284f3a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#cee99d';ctx.globalAlpha=.14;ctx.beginPath();ctx.arc(w*.76,h*.3,45+t*12,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;for(let layer=0;layer<3;layer++){ctx.fillStyle=['#355f44','#477448','#658751'][layer];ctx.beginPath();ctx.moveTo(0,h);ctx.lineTo(0,h*(.5+layer*.13));for(let x=0;x<=w;x+=12){ctx.lineTo(x,h*(.5+layer*.13)+Math.sin(x/w*5+layer+t*2)*h*.055);}ctx.lineTo(w,h);ctx.fill();}ctx.strokeStyle='#c4e99035';ctx.lineWidth=1;for(let i=-4;i<12;i++){ctx.beginPath();ctx.moveTo(w/2+(i-4)*16,h*.59);ctx.lineTo((i-4)*w*.2,h);ctx.stroke();}for(let i=0;i<18;i++){const x=(i*43+w*.04)%w,y=h*.71+(i%4)*h*.055,length=16+(i%3)*6+t*18+period*4,sway=reduced?0:Math.sin(now/1200+i)*4;ctx.strokeStyle='#b8d683';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+sway,y-length*.5,x+sway*1.6,y-length);ctx.stroke();ctx.fillStyle=i%3?'#95bd68':'#c5db83';ctx.beginPath();ctx.ellipse(x+sway-6,y-length*.6,8,3,-.5,0,Math.PI*2);ctx.ellipse(x+sway+5,y-length*.8,7,3,.5,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#eff9d9';ctx.font='12px Segoe UI, Microsoft YaHei';ctx.fillText(S.videoReady?S.videoName+' / '+periodNames[S.period]+'创作片段':'GENGYUN / FIELD CANVAS',22,h-26);if(S.videoReady){const time=$('#video-time'),seek=$('#video-seek');if(time)time.textContent=formatTime(S.time)+' / 00:16';if(seek)seek.value=S.time;const play=$('[data-action="play"]');if(play)play.innerHTML=icon(S.playing?'pause':'play');}frame=requestAnimationFrame(draw);}frame=requestAnimationFrame(draw);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-route],[data-action]');if(!el)return;if(el.dataset.route){go(el.dataset.route);return;}const a=el.dataset.action,id=el.dataset.id;switch(a){
 case 'phone':document.body.classList.toggle('phone-mode');render();break;
 case 'close':close();break;
 case 'scan-mode':if(S.scanning)clearInterval(processTimer);S.scanning=false;S.progress=0;S.scanMode=el.dataset.mode;render();break;
 case 'upload':$('#image-input').click();break;
 case 'sample':if(S.photo)URL.revokeObjectURL(S.photo);S.photo='';render();toast('已选择内置示例，可以开始模拟识别');break;
 case 'scan':simulate('scan');break;
 case 'result-video':S.videoName=$('#confirmed-name').value.trim()||'演示制剂 A';go('video');break;
 case 'category':libraryFilter=el.dataset.category;libraryRegion='全部';libraryRisk='全部';render();break;
 case 'favorite':S.favorites=S.favorites.includes(id)?S.favorites.filter(v=>v!==id):[...S.favorites,id];persist();render();toast(S.favorites.includes(id)?'已加入本地收藏':'已取消收藏');break;
 case 'period':clearInterval(processTimer);S.generating=false;S.period=el.dataset.period;S.videoReady=false;S.playing=false;S.time=0;S.progress=0;render();break;
 case 'generate':simulate('video');break;
 case 'play':if(S.videoReady){if(S.time>=16)S.time=0;S.playing=!S.playing;}break;
 case 'restart':S.time=0;S.playing=true;break;
 case 'suggest':ask(el.dataset.text);break;
 case 'voice':if(recordingTimer)return;el.classList.add('sound-active');toast('正在模拟语音输入，不访问麦克风');recordingTimer=setTimeout(()=>{recordingTimer=null;el.classList.remove('sound-active');const input=$('#chat-input');if(input){input.value='如何拍摄一张清晰的标签？';input.focus();toast('示例语音已转为文字，可以发送');}},1200);break;
 case 'speak':speak(el.dataset.text);break;
 case 'feed-filter':communityFilter=el.dataset.filter;render();break;
 case 'like':S.likes=S.likes.includes(id)?S.likes.filter(v=>v!==id):[...S.likes,id];persist();render();break;
 case 'topic':modal('田间话题',`<p class="hint">${esc(el.dataset.text)}</p><p class="notice">这是示例话题。可以分享你的观察，体验社区发布流程。</p>${btn('分享发现','compose','primary full')}`);break;
 case 'compose':modal('分享一次田间发现',`<form id="post-form"><label class="label" for="post-text">今天发现了什么？</label><textarea class="textarea" id="post-text" maxlength="600" placeholder="记录你的观察、问题或心得…" required></textarea><p class="hint">作物：${esc(S.crop)} · 仅保存到本机</p><p class="notice">发布与审核是前端模拟，不会发送到真实社区。</p><button class="btn primary full" type="submit">发布演示动态</button></form>`);break;
 case 'report':modal('反馈这条内容',`<p class="hint">体验反馈入口，不会提交真实举报。</p><label class="label" for="report-reason">反馈原因</label><select class="input" id="report-reason"><option>信息不准确</option><option>不适合社区</option><option>其他问题</option></select><div class="form-gap">${btn('提交演示反馈','report-submit','primary full')}</div>`);break;
 case 'report-submit':close();toast('已完成演示反馈 · 未向服务器提交');break;
 case 'message-filter':messageFilter=el.dataset.filter;render();break;
 case 'read-all':S.read=notifications.map(n=>n.id);persist();render();toast('已将演示消息全部标为已读');break;
 case 'message':{const n=notifications.find(v=>v.id===id);if(!n)break;if(!S.read.includes(id))S.read.push(id);persist();render();modal(n.title,`<p class="hint">${n.text}</p><p class="modal-note">${n.time} · 演示消息</p>${btn('查看相关页面','message-open','primary full',`data-dest="${n.route}"`)}`);break;}
 case 'message-open':close();go(el.dataset.dest);break;
 case 'edit-profile':modal('编辑个人资料',`<form id="profile-form"><label class="label" for="profile-name">昵称</label><input class="input" id="profile-name" value="${esc(S.name)}" maxlength="20" required><div class="form-gap"><button class="btn primary full" type="submit">保存到本机</button></div></form>`);break;
 case 'crop':modal('选择你关注的作物',`<p class="hint">用于调整界面中的作物偏好。</p><div class="crop-select-grid">${['水稻','玉米','小麦','蔬菜'].map(c=>`<button class="crop-choice ${S.crop===c?'selected':''}" data-action="choose-crop" data-crop="${c}">${icon('wheat')}<strong>${c}</strong>${S.crop===c?icon('check'):''}</button>`).join('')}</div>`);break;
 case 'choose-crop':S.crop=el.dataset.crop;persist();close();render();toast('已关注 '+S.crop);break;
 case 'toggle-voice':S.voice=!S.voice;persist();render();break;
 case 'privacy':modal('隐私与授权',`<div class="prose"><p>本原型不上传照片，不连接后端。昵称、收藏、点赞、作物偏好与演示发布保存在当前浏览器。</p><p>语音输入为预置文字模拟；朗读使用浏览器本地能力。</p><p>正式版本的用途授权、撤回与删除流程将在小程序中实现，本页只展示入口。</p></div>${btn('清除本地演示数据','reset','ghost full')}`);break;
 case 'about':modal('关于耕云 Demo',`<div class="login-mark">${icon('leaf')}</div><p class="hint">耕云 · 看见田间的可能</p><p class="notice">网页版用户端原型，覆盖五个主入口与核心探索流程。用于确认视觉与交互，后续小程序参照实现。</p><p class="modal-note">v1.0 / 前端模拟</p>`);break;
 case 'favorites':modal('我的收藏',S.favorites.length?`<div class="info-list">${S.favorites.map(id=>{const a=articles.find(v=>v.id===id);return a?link(a.title,`article/${id}`,'info-row'):'';}).join('')}</div>`:'<div class="empty">还没有收藏，去资料库发现一些内容吧。</div>'+btn('浏览资料库','modal-library','primary full'));break;
 case 'modal-library':close();go('library');break;
 case 'history':modal('探索记录',`<div class="info-list">${link('识草观察 · 示例记录','identify','info-row')}${link('标签确认 · 示例记录','article/label','info-row')}${link('情景视频 · 示例记录','video','info-row')}</div><p class="modal-note">记录为界面示例。</p>`);break;
 case 'my-posts':modal('我的发布',S.posts.length?`<div class="info-list">${S.posts.map(p=>link(esc(p.text.slice(0,35)),`post/${p.id}`,'info-row')).join('')}</div>`:'<div class="empty">还没有本地发布。</div>'+btn('分享发现','compose','primary full'));break;
 case 'reset':modal('重置演示数据',`<p class="hint">将清除本 Demo 的昵称、偏好、收藏、点赞和发布，不影响其他网站的数据。</p><div class="row-actions">${btn('取消','close','ghost')}${btn('确认重置','reset-confirm','danger')}</div>`);break;
 case 'reset-confirm':try{localStorage.removeItem(KEY);}catch{}location.reload();break;
 case 'logout':S.logged=false;persist();go('home');toast('已退出演示账号');break;
 case 'login':login();break;
 }});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;switch(f.id){case 'chat-form':ask($('#chat-input').value);break;case 'comment-form':{const t=$('#comment-input').value.trim();if(!t)return;(comments[f.dataset.id]??=[]).push(t);render();toast('演示评论已保存到当前页面');break;}case 'login-form':S.name=$('#login-name').value.trim()||'田间探索者';S.logged=true;persist();close();go(f.dataset.dest);toast('已进入演示账号');break;case 'profile-form':S.name=$('#profile-name').value.trim()||'田间探索者';persist();close();render();toast('资料已保存到本机');break;case 'post-form':{const text=$('#post-text').value.trim();if(!text)return;S.posts.unshift({id:'p'+Date.now().toString(36),name:S.name,crop:S.crop,time:'刚刚 · 本地演示发布',text,art:false,likes:0,comments:0});persist();close();go('community');toast('模拟审核完成，演示动态已发布');break;}}});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){libraryQuery=e.target.value;$('#library-results').innerHTML=libraryCards();}if(e.target.id==='video-seek'){S.time=Number(e.target.value);lastFrame=0;}if(e.target.id==='video-name'){S.videoName=e.target.value;S.videoReady=false;S.playing=false;S.time=0;}});
$('#image-input').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('请选择图片文件');return;}if(S.photo)URL.revokeObjectURL(S.photo);S.photo=URL.createObjectURL(file);e.target.value='';render();toast('图片已在本地预览，识别仍为模拟');});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')close();if(e.key==='Tab'){const list=[...$('.modal').querySelectorAll('button,input,textarea,select,[tabindex="0"]')];const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#modal-root').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close();if(e.target.closest('[data-route]'))close();});
window.addEventListener('hashchange',route);
window.addEventListener('beforeunload',()=>{if(S.photo)URL.revokeObjectURL(S.photo);});
route();

document.addEventListener('change',e=>{if(e.target.id==='library-region')libraryRegion=e.target.value;else if(e.target.id==='library-risk')libraryRisk=e.target.value;else return;$('#library-results').innerHTML=libraryCards();});
